    if (sel("attn_dense_h256_gqa4_bf16")) {
        au::attn_window_right_cases(pl, "attn_dense_h256_gqa4_bf16", 4, 1, 256, 257);
        au::attn_window_right_cases(pl, "attn_dense_h256_gqa4_bf16", 4, 1, 9, 0);
    }
